(function(root){
'use strict';
const legacyKey='lifeline-archived-lives-v1';let worker=null,sequence=0,activeHost=null,inflight=false,attached=null;const callbacks=new Map();
function spawn(){if(worker)return;worker=new Worker('reference/worker.js');worker.onmessage=({data})=>{const cb=callbacks.get(data.id);if(!cb)return;callbacks.delete(data.id);data.ok?cb.resolve(data.value):cb.reject(new Error(data.error));};worker.onerror=e=>{for(const cb of callbacks.values())cb.reject(new Error(e.message||'Не удалось загрузить движок'));callbacks.clear();};}
function call(command,payload={}){spawn();return new Promise((resolve,reject)=>{const id=++sequence;callbacks.set(id,{resolve,reject});worker.postMessage({id,command,payload});});}
const normalize=(value)=>value==null?'':String(value).replace(/&quot;/g,'"').replace(/&#39;/g,"'");
function scene(raw){const id=raw.pending?.id||'',job=raw.job||'';if(/school|college|uni|phd|study/.test(id)||raw.school)return raw.age<18?'school':'read';if(/job|biz|work|career/.test(id))return 'work';if(/kid|wed|partner|family|parent/.test(id))return 'family';if(/move|abroad|trip|travel/.test(id))return 'park';return raw.age<1?'home':raw.focus==='sport'||raw.focus==='health'?'park':raw.focus==='hobby'?'draw':raw.focus==='family'||raw.focus==='play'?'family':raw.focus==='study'||raw.focus==='learn'||raw.focus==='mind'?'read':raw.focus==='work'?'work':'home';}
function map(host,snapshot){const raw=snapshot.raw,oldPlaying=!!host.flow.playing,first=!host.reference;host.reference={version:1,snapshot};host.age=raw.age;host.ended=raw.phase==='dead';host.origin.name=normalize(raw.name?.full||host.origin.name);host.origin.sex=raw.sex==='M'?'male':'female';host.origin.currentCountry=snapshot.country.name;host.origin.referenceApprox=snapshot.country.approx;
 host.stats.health=Math.round(raw.st.hl);host.stats.joy=Math.round(raw.st.h);host.stats.skill=Math.round(raw.st.sm);host.stats.bond=Math.round(raw.st.so);host.childhood.finished=true;
 const fm=raw.fam||{};for(const [role,key]of [['mother','mom'],['father','dad']]){const person=fm[key];if(person){host.family[role]={...host.family[role],name:normalize(person.name?.g||person.name?.full||host.family[role].name),alive:person.alive!==false&&!person.absent,job:snapshot.parentJobs?.[key]||host.family[role].job};}else host.family[role]={...host.family[role],alive:false};}
 host.family.grandmother={...host.family.grandmother,alive:false};
 host.family.wealth=raw.q<=2?'modest':raw.q>=4?'wealthy':'steady';
 const peopleName=p=>normalize(p?.name?.full||p?.name?.g||p?.name||'Близкий человек'),partner=fm.partner&&fm.partner.alive!==false?peopleName(fm.partner):null;
 host.social.partner=partner?{name:partner,closeness:Math.round(fm.partner.so??raw.st.so),values:'independent',changed:false}:null;
 const active=snapshot.pending?{kind:'life',id:snapshot.pending.id,key:snapshot.pending.id,title:normalize(snapshot.pending.title),text:normalize(snapshot.pending.text),fact:normalize(snapshot.pending.fact),question:snapshot.pending.question,name:snapshot.pending.name,scene:scene(raw),options:snapshot.pending.choices.map(c=>({key:c.key,title:normalize(c.title),hint:normalize(c.hint),disabled:c.disabled}))}:null;
 const year=raw.years?.at(-1),f={balance:raw.money,debt:snapshot.debt,invested:Math.max(0,snapshot.netWorth-raw.money-(raw.house||0)),income:raw.income||0,expenses:0,interest:0,owner:'self',ledger:[]};if(year?.fl?.it)f.ledger=Object.entries(year.fl.it).map(([label,amount])=>({month:year.a*12,label,amount:typeof amount==='number'?amount:amount.v||0}));
 const d={version:1,reference:true,focus:raw.focus||'health',active,education:raw.school||raw.edu,job:snapshot.job,home:snapshot.country.name,partner,children:(fm.kids||[]).filter(k=>k.alive!==false).map(k=>({name:peopleName(k),born:(k.bornAt??raw.age-(k.age||0))*12})),contacts:[],finance:f,actions:{year:raw.age,used:0,byId:{}},world:{fallback:snapshot.country.approx?['additional-country']:[]},ending:raw.deathAt?{reason:normalize(raw.deathAt.label||raw.deathAt.cause||'История жизни завершена.')} : null};
 host.flow.simulation=d;host.flow.decisions=d;host.flow.simple=true;host.flow.months=raw.age*12+Math.min(11,Math.floor((raw.t||0)*12));host.flow.activity=scene(raw);host.flow.playing=oldPlaying&&!host.ended;host.flow.feed=(raw.log||[]).map((row,i)=>({id:'reference-'+i,month:Math.round((row.a||0)*12),type:row.kind==='dec'?'choice':row.kind==='loss'?'consequence':row.kind==='warm'?'milestone':'event',text:normalize(row.text),title:normalize(row.q||''),scene:scene(raw)}));
 if(first)host.referenceLegacyHistory=host.history.slice();host.history=host.flow.feed.map(e=>({age:e.month/12,title:e.title,choice:e.title,text:e.text,delta:{}}));return host;
}
function notify(){if(typeof root.onReferenceUpdate==='function')root.onReferenceUpdate();}
function action(command,payload={}){if(inflight||!activeHost)return false;inflight=true;const host=activeHost;call(command,payload).then(value=>{if(host!==activeHost)return;map(host,value);inflight=false;if(host.uiHints&&command==='choose')delete host.uiHints.deferredDecision;notify();}).catch(error=>{if(typeof root.onReferenceError==='function')root.onReferenceError(error.message);}).finally(()=>{inflight=false;});return true;}
async function create(host){inflight=true;activeHost=host;try{const value=await call('new',{seed:'lifeline-'+host.seed,country:host.origin.iso3});map(host,value);attached=host;return host;}finally{inflight=false;}}
function attach(host){activeHost=host;if(attached===host)return;attached=host;inflight=true;call('restore',{raw:host.reference.snapshot.raw,seed:host.reference.snapshot.seed,draws:host.reference.snapshot.draws}).then(value=>{if(activeHost===host){map(host,value);inflight=false;notify();}}).catch(e=>root.onReferenceError?.(e.message)).finally(()=>{inflight=false;});}
function archive(host){try{const lives=JSON.parse(localStorage.getItem(legacyKey)||'[]');lives.unshift({at:Date.now(),state:JSON.parse(JSON.stringify(host))});localStorage.setItem(legacyKey,JSON.stringify(lives.slice(0,5)));}catch{}}
function archived(){try{return JSON.parse(localStorage.getItem(legacyKey)||'[]');}catch{return [];}}
function group(id){if(/check|dent|med|treat|quit|rehab|therapy|vax|sport|gym|drug|alcohol/.test(id))return 'health';if(/ged|nightgrad|openuni|nightuni|tutor|course|study|book/.test(id))return 'study';if(/job|biz|work|runprep|dreamjob/.test(id))return 'work';if(/meet|parent|kid|split|propos|dinner|marri|wed|donat|cust|movehome|sur/.test(id))return 'people';if(/gear|hobby|lesson|trip|abroad|travel|instrument/.test(id))return 'hobby';return 'money';}
const sim=root.LifeSimulation,flow=root.LifeFlow,oldSim={...sim},oldFlow={...flow};
for(const name of ['ensure','pending','focuses','setFocus','occupation','actions','perform','money','drain']){sim[name]=function(host,...args){if(!host.reference)return oldSim[name](host,...args);const snap=host.reference.snapshot,d=host.flow.simulation;
 switch(name){case'ensure':return d;case'pending':return host.ended?null:d.active;case'focuses':return host.ended?[]:snap.focus;case'setFocus':return action('focus',{key:args[0]});case'occupation':return snap.job;case'money':return d.finance;case'drain':return [];case'actions':{if(host.ended)return [];const section=args[0]||'all';return snap.shop.filter(a=>section==='all'||section==='money'||group(a.id)===section).map(a=>({...a,group:group(a.id),reason:d.active?'Сначала завершите текущий выбор':a.reason,disabled:inflight||!!d.active||a.disabled}));}case'perform':{const item=sim.actions(host).find(a=>a.id===args[0]);if(!item||item.disabled)return {ok:false,text:item?.reason||'Сейчас это действие недоступно.'};return {ok:action('buy',{key:item.id}),pending:true,text:'Выполняется…'};}}
 };}
flow.pending=function(host){return host.reference?sim.pending(host):oldFlow.pending(host);};
flow.advanceYear=function(host){if(!host.reference)return oldFlow.advanceYear(host);if(host.ended||sim.pending(host))return false;activeHost=host;return action('advance');};
flow.advanceToEvent=function(host){if(!host.reference)return oldFlow.advanceToEvent(host);if(host.ended||sim.pending(host))return false;activeHost=host;return action('advance',{until:'event'});};
flow.resolve=function(host,index,extra){if(!host.reference)return oldFlow.resolve(host,index);const choice=sim.pending(host)?.options[index];if(!choice||choice.disabled)return false;activeHost=host;action('choose',{key:choice.key,extra});return false;};
flow.begin=function(host){if(!host.reference)return oldFlow.begin(host);host.started=true;host.born=true;host.flow.playing=true;activeHost=host;action('begin');return true;};
flow.occupation=function(host,role='self'){return host.reference&&role==='self'?host.reference.snapshot.job:host.reference&&['mother','father'].includes(role)?host.family[role].job:oldFlow.occupation(host,role);};
root.ReferenceController={create,attach,archive,archived,action,busy:()=>inflight,active:host=>!!host?.reference,call};
})(window);
